import { spawn } from "child_process"

// 🛡️ 定义允许执行的命令白名单
const ALLOWED_COMMANDS = {
	ping: {
		binary: 'ping',
		argsValidator: (args: string[]) => {
			// 最多接受一个参数（目标主机）
			if (args.length > 1) return false
			// 验证IP地址或域名格式
			const valid = /^(?=.{1,255}$)[0-9]{1,3}(\.[0-9]{1,3}){3}$|[a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(\.[a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$/.test(args[0] || '')
			return valid
		}
	},
	date: {
		binary: 'date',
		argsValidator: (args: string[]) => {
			// date命令不允许任何参数
			return args.length === 0
		}
	},
	uptime: {
		binary: 'uptime',
		argsValidator: (args: string[]) => {
			// uptime命令不允许任何参数
			return args.length === 0
		}
	}
}

/**
 * ✅ 安全命令执行器
 * 使用白名单机制，只允许执行预定义的命令
 */
export async function executeSafely(commandName: string, ...args: string[]): Promise<string> {
	// 检查命令是否在白名单中
	const allowed = ALLOWED_COMMANDS[commandName as keyof typeof ALLOWED_COMMANDS]
	if (!allowed) {
		throw new Error(`Command '${commandName}' is not allowed`)
	}

	// 验证参数
	if (!allowed.argsValidator(args)) {
		throw new Error(`Invalid arguments for command '${commandName}'`)
	}

	// 使用 spawn 而不是 exec，避免 Shell 解析
	return new Promise((resolve, reject) => {
		const process = spawn(allowed.binary, args, {
			// 限制资源使用，防止DoS攻击
			rlimit: {
				cpu: 10,     // CPU限制：10秒
				data: '1MB', // 内存限制：1MB
				maxrss: 100 * 1024 * 1024, // RSS内存限制：100MB
			},
			// 不使用环境变量，防止环境信息泄露
			shell: false,
		})

		let stdout = ''
		let stderr = ''

		process.stdout?.on('data', (data) => {
			stdout += data.toString()
			// 限制输出大小，防止输出DoS
			if (stdout.length > 10 * 1024) { // 10KB限制
				process.kill()
				reject(new Error('Output size limit exceeded'))
			}
		})

		process.stderr?.on('data', (data) => {
			stderr += data.toString()
			// 同样限制错误输出
			if (stderr.length > 10 * 1024) {
				process.kill()
				reject(new Error('Error output size limit exceeded'))
			}
		})

		process.on('close', (code) => {
			if (code !== 0) {
				reject(new Error(`Command failed with code ${code}: ${stderr}`))
			} else {
				resolve(stdout)
			}
		})

		process.on('error', (err) => {
			reject(err)
		})

		// 设置超时，防止命令挂起
		setTimeout(() => {
			process.kill('SIGKILL')
			reject(new Error('Command timeout after 10 seconds'))
		}, 10000)
	})
}

