import { execFileSync } from 'child_process'

/**
 * ✅ 使用专用的命令执行库
 * 这里演示如何正确解析和执行命令，同时保持安全性
 */
export class CommandExecutor {
	private static sanitizeArgs(args: string[]): string[] {
		return args.map(arg => {
			// 移除危险字符
			const dangerousChars = /[|&;<>$()`"'\\]/g
			if (dangerousChars.test(arg)) {
				throw new Error(`Argument contains dangerous characters: ${arg}`)
			}
			return arg
		})
	}

	static async execute(command: string, args: string[] = []): Promise<string> {
		// 验证命令名称
		const commandRegex = /^[a-z0-9_-]+$/i
		if (!commandRegex.test(command)) {
			throw new Error(`Invalid command name: ${command}`)
		}

		// 清理参数
		const sanitizedArgs = this.sanitizeArgs(args)

		try {
			// 使用 execFileSync 而不是 exec，避免 Shell 解析
			const output = execFileSync(command, sanitizedArgs, {
				encoding: 'utf8',
				maxBuffer: 10 * 1024, // 10KB缓冲区限制
				timeout: 10000,      // 10秒超时
			})
			return output
		} catch (error) {
			throw new Error(`Command execution failed: ${error}`)
		}
	}
}

