// 不要使用：execAsync('ping 8.8.8.8')
// 改用：
import { createSocket } from 'dgram'
import { promisify } from 'util'

async function pingHostTarget(host: string): Promise<boolean> {
	// 使用Node.js ICMP库，而不是系统ping命令
	// 这里只是一个概念示例，实际实现会更复杂
	return new Promise((resolve) => {
		const socket = createSocket('udp4')
		socket.send(Buffer.from('ping'), 0, 4, 80, host, (err) => {
			socket.close()
			resolve(!err)
		})
	})
}

