// 不要使用：execAsync('cat /etc/passwd')
// 改用：使用fs模块读取文件
import { readFile } from 'fs/promises'

async function readFileSafely(filePath: string): Promise<string> {
	// 🛡️ 严格验证文件路径，防止目录遍历攻击
	const resolvedPath = require('path').resolve(filePath)
	const allowedBasePaths = ['/etc', '/var/log', '/home']

	const isAllowed = allowedBasePaths.some(basePath => 
		resolvedPath.startsWith(basePath)
	)

	if (!isAllowed) {
		throw new Error(`Access to file '${filePath}' is not allowed`)
	}

	return await readFile(resolvedPath, 'utf8')
}

