import winston from 'winston'

const logger = winston.createLogger({
	level: 'info',
	format: winston.format.combine(
		winston.format.timestamp(),
		winston.format.json()
	),
	transports: [
		new winston.transports.File({ filename: 'command-exec.log' }),
		new winston.transports.Console()
	]
})

async function executeWithAudit(commandName: string, args: string[], user: string): Promise<string> {
	// 记录执行前的状态
	logger.info({
		event: 'command_execution_start',
		command: commandName,
		args: args,
		user: user,
		timestamp: new Date().toISOString()
	})

	try {
		const result = await executeSafely(commandName, ...args)

		// 记录成功执行
		logger.info({
			event: 'command_execution_success',
			command: commandName,
			user: user,
			timestamp: new Date().toISOString()
		})

		return result
	} catch (error) {
		// 记录失败的执行尝试
		logger.warn({
			event: 'command_execution_failed',
			command: commandName,
			args: args,
			user: user,
			error: error instanceof Error ? error.message : String(error),
			timestamp: new Date().toISOString()
		})

		// 如果检测到可疑行为，触发警报
		if (isSuspiciousActivity(commandName, args)) {
			logger.error({
				event: 'SECURITY_ALERT',
				type: 'suspicious_command_attempt',
				command: commandName,
				args: args,
				user: user,
				timestamp: new Date().toISOString()
			})
			// 可以集成到SIEM系统
			// sendAlertToSIEM({ type: 'command_injection', user, command: commandName })
		}

		throw error
	}
}

function isSuspiciousActivity(commandName: string, args: string[]): boolean {
	// 检测可疑的参数模式
	const suspiciousPatterns = [
		/[|&;<>$]/,                    // Shell元字符
		/\.\.\//,                     // 路径遍历
		/\$\(|`|\\x/,                  // 命令替换
		/(?i)(rm|del|format)/,        // 破坏性命令
		(?i)(curl|wget|nc|telnet)/,   // 网络工具
		(?i)(chmod|chown)/            // 权限修改
	]

	return suspiciousPatterns.some(pattern => 
		pattern.test(commandName) || args.some(arg => pattern.test(arg))
	)
}

